import { Injectable, NotFoundException } from '@nestjs/common';
import { Database } from '../database.module';
import { PageDto, paginated } from '../common/page.dto';
import { CompanyDto, DepartmentDto, PositionDto, UpdateDepartmentDto } from './organization.dto';

@Injectable()
export class OrganizationService {
 constructor(private db: Database) {}
 async company(companyId: string) {
  const data = await this.db.company.findUnique({where:{id:companyId}});
  if (!data) throw new NotFoundException();
  return {data};
 }
 async updateCompany(companyId: string, dto: CompanyDto) {
  return {data:await this.db.company.update({where:{id:companyId},data:dto})};
 }
 async departments(companyId: string, q: PageDto) {
  const where = {companyId, ...(q.search ? {name:{contains:q.search,mode:'insensitive' as const}} : {})};
  const [data,total] = await this.db.$transaction([
   this.db.department.findMany({where,orderBy:[{name:'asc'},{id:'asc'}],skip:(q.page-1)*q.pageSize,take:q.pageSize,include:{_count:{select:{employees:true}}}}),
   this.db.department.count({where}),
  ]);
  return paginated(data,total,q);
 }
 async department(companyId: string, id: string) {
  const data = await this.db.department.findUnique({where:{companyId_id:{companyId,id}}});
  if (!data) throw new NotFoundException();
  return {data};
 }
 async createDepartment(companyId: string, dto: DepartmentDto) {
  return {data:await this.db.department.create({data:{...dto,companyId}})};
 }
 async updateDepartment(companyId: string, id: string, dto: UpdateDepartmentDto) {
  return {data:await this.db.department.update({where:{companyId_id:{companyId,id}},data:dto})};
 }
 async positions(companyId: string, q: PageDto) {
  const where = {companyId,...(q.search ? {title:{contains:q.search,mode:'insensitive' as const}} : {})};
  const [data,total] = await this.db.$transaction([
   this.db.position.findMany({where,orderBy:[{title:'asc'},{id:'asc'}],skip:(q.page-1)*q.pageSize,take:q.pageSize}),
   this.db.position.count({where}),
  ]);
  return paginated(data,total,q);
 }
 async createPosition(companyId: string, dto: PositionDto) {
  // The composite FK also enforces tenancy if the department changes concurrently.
  await this.department(companyId,dto.departmentId);
  return {data:await this.db.position.create({data:{...dto,companyId}})};
 }
}

